contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(caller != address(0));
        require(caller != address(this));
        require(address(this).balance >= 0);

        uint256 balanceBefore = address(c).balance;

        // Make the test contract the caller of withdrawAll
        bool reverted;
        c.withdrawAll(caller); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Since C's constructor is called by this contract, and C.owner is set to this test contract's address,
        // a call from this test contract should NOT revert.
        // A call from any other address would revert, but we cannot simulate another msg.sender here.
        // Therefore assert that the owner can always drain the contract to the recipient.
        assert(!reverted);
    }

    receive() external payable {}
}

